static req_t * find_req_entry ( char * device , uint_t flag , int seq_num , req_list_t * list ) { int i ; for ( i = 0 ; i < list -> n_req_max ; i ++ ) { if ( ( strcmp ( device , list -> req [ i ] . device ) != 0 ) || ( list -> req [ i ] . flag & RCM_FILESYS ) != ( flag & RCM_FILESYS ) ) { continue ; } if ( ( seq_num != - 1 ) && ( ( seq_num >> SEQ_NUM_SHIFT ) != ( list -> req [ i ] . seq_num >> SEQ_NUM_SHIFT ) ) ) { continue ; } return ( & list -> req [ i ] ) ; } return ( NULL ) ; } 